// ignore_for_file: deprecated_member_use, avoid_web_libraries_in_flutter
import 'dart:html' as html;

const _sounds = <String, String>{
  'message':
      '',
  'mention':
      '',
  'call':
      '',
  'notification':
      '',
};


Future<bool> unlockChatAudio() async {
  final data = _sounds['notification'];
  if (data == null) return false;
  final audio = html.AudioElement('data:audio/wav;base64,$data')
    ..preload = 'auto'
    ..volume = 0.0;
  try {
    // Must be invoked synchronously from a real pointer/click activation.
    await audio.play();
    audio.pause();
    audio.currentTime = 0;
    return true;
  } catch (_) {
    return false;
  }
}

Future<void> playChatSound(String event) async {
  final key = switch (event) {
    'call' => 'call',
    'mention' || 'warning' => 'mention',
    'friendRequest' || 'notification' || 'gift' => 'notification',
    _ => 'message',
  };
  final data = _sounds[key];
  if (data == null) return;
  final audio = html.AudioElement('data:audio/wav;base64,$data')
    ..preload = 'auto'
    ..volume = 0.72;
  try {
    await audio.play();
  } catch (_) {}
}
